function reviewSubmission(data){const issues=[];if(!data.subcategory)issues.push('Choose a research subcategory.');if((data.sources||'').trim().length<15)issues.push('Add full references and links to your sources.');if(!data.originality_declaration)issues.push('Confirm your originality and AI-use declaration.');const body=data.body||'';if(!/\([A-Za-z][^)]*,?\s*\d{4}\)|\[\d+\]|doi:|https?:\/\//i.test(body))issues.push('Add in-text citations or source markers to your article before submitting.');return issues}

