const LOCAL_KEY='anatry_research_drafts_v2';
function getLocalDrafts(){try{return JSON.parse(localStorage.getItem(LOCAL_KEY)||'[]')}catch{return []}}
function storeLocalDrafts(list){try{const raw=JSON.stringify(list);localStorage.setItem(LOCAL_KEY,raw);return localStorage.getItem(LOCAL_KEY)===raw}catch(e){console.error('Draft storage failed',e);return false}}
function sanitizeRich(html){const doc=new DOMParser().parseFromString('<div>'+String(html||'')+'</div>','text/html');const allowed=new Set(['DIV','P','BR','B','STRONG','I','EM','U','S','H1','H2','H3','UL','OL','LI','BLOCKQUOTE','SPAN','FONT','IMG']);function clean(node){for(const child of [...node.children]){if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes);continue}for(const attr of [...child.attributes]){const key=attr.name.toLowerCase(),v=attr.value;if(child.tagName==='IMG'&&key==='src'&&/^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(v))continue;if(key==='style'&&v.length<400&&!/[<>]/.test(v)&&v.split(';').every(part=>!part.trim()||/^(font-family|font-size|color|text-align|background-color|text-decoration|text-decoration-color|text-decoration-thickness|float|margin|width|display)\s*:/i.test(part.trim())))continue;if(child.tagName==='FONT'&&['face','size','color'].includes(key))continue;child.removeAttribute(attr.name)}clean(child)}}const root=doc.body.firstElementChild;clean(root);return root.innerHTML}
function localDraftEditor(id){const d=getLocalDrafts().find(x=>x.id===id)||{id:crypto.randomUUID(),title:'',discipline:'Medicine',abstract:'',body:'',doc_url:''};modal(`<div class="doc-modal"><div class="doc-header"><div><span class="eyebrow">ANATRY RESEARCH STUDIO · DOCUMENT EDITOR</span><h2 class="page-title">${esc(d.title||'Untitled research')}</h2><p class="muted">Write, format, add images and save your work in this browser.</p></div><span class="pill goldpill" id="saveStatus">Not saved yet</span></div><form id="localDraftForm"><input type="hidden" name="id" value="${esc(d.id)}"><div class="doc-meta"><div><label class="label">Document title</label><input class="field" name="title" required maxlength="160" value="${esc(d.title)}" placeholder="Your research paper title"></div><div><label class="label">Discipline</label><select class="field" name="discipline">${fields.map(f=>`<option ${d.discipline===f?'selected':''}>${f}</option>`).join('')}</select></div></div><label class="label">Abstract / overview</label><textarea class="field" name="abstract" maxlength="2000" placeholder="Summarize your research question and findings">${esc(d.abstract)}</textarea><div class="doc-toolbar" role="toolbar" aria-label="Document formatting"><select id="docFont" aria-label="Font family"><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Times New Roman">Times New Roman</option><option value="Verdana">Verdana</option><option value="Courier New">Courier New</option><option value="Garamond">Garamond</option><option value="Palatino Linotype">Palatino</option><option value="Trebuchet MS">Trebuchet</option><option value="Tahoma">Tahoma</option><option value="Cambria">Cambria</option><option value="Book Antiqua">Book Antiqua</option><option value="Helvetica">Helvetica</option><option value="Baskerville">Baskerville</option><option value="Didot">Didot</option><option value="Avenir">Avenir</option><option value="Optima">Optima</option><option value="Futura">Futura</option><option value="Gill Sans">Gill Sans</option><option value="Century Gothic">Century Gothic</option><option value="Bookman Old Style">Bookman</option><option value="Lucida Sans">Lucida Sans</option><option value="Franklin Gothic Medium">Franklin Gothic</option><option value="Consolas">Consolas</option><option value="Impact">Impact</option><option value="Comic Sans MS">Comic Sans</option></select><select id="docHeading" aria-label="Paragraph style"><option value="P">Normal text</option><option value="H1">Heading 1</option><option value="H2">Heading 2</option><option value="H3">Heading 3</option></select><select id="docTemplate" aria-label="Research template"><option value="">Insert a template…</option><option value="research">Research paper (IMRaD)</option><option value="magazine">Science magazine feature</option><option value="medicine">Medicine / clinical review</option><option value="biology">Biology / lab report</option><option value="chemistry">Chemistry / experiment</option><option value="physics">Physics / investigation</option></select><select id="docSize" aria-label="Font size"><option value="2">Small</option><option value="3" selected>Normal</option><option value="4">Large</option><option value="5">XL</option><option value="6">Title</option></select><button type="button" data-format="bold" title="Bold"><b>B</b></button><button type="button" data-format="italic" title="Italic"><i>I</i></button><button type="button" data-format="underline" title="Underline"><u>U</u></button><button type="button" data-format="insertUnorderedList" title="Bulleted list">☷</button><button type="button" data-format="insertOrderedList" title="Numbered list">1.</button><button type="button" data-format="justifyLeft" title="Align left">≡</button><button type="button" data-format="justifyCenter" title="Align center">☰</button><label class="doc-color" title="Text color">A <input type="color" id="docColor" value="#172c25" aria-label="Text color"></label><label class="doc-color" title="Highlight selected text">Highlight <input type="color" id="docHighlight" value="#fff0a8" aria-label="Highlight color"></label><label class="doc-color" title="Underline color">Underline <input type="color" id="docUnderlineColor" value="#c49334" aria-label="Underline color"></label><button type="button" data-action="insertImage" title="Insert a photo">▣ Photo</button><input type="file" id="docImageInput" accept="image/png,image/jpeg,image/webp" hidden><button type="button" data-action="insertRule" title="Insert divider">— Divider</button><button type="button" data-action="insertQuote" title="Insert quotation">❝ Quote</button><button type="button" data-action="toggleMagazine" title="Toggle magazine page style">✦ Magazine</button><button type="button" data-action="docFullscreen" title="Expand editor to full screen">⛶ Full screen</button><button type="button" data-format="undo" title="Undo">↶</button><button type="button" data-format="redo" title="Redo">↷</button></div><div class="doc-image-tools" id="docImageTools" hidden><span>Selected image</span><label>Width <input id="docImageWidth" type="range" min="15" max="100" value="80" step="5"></label><span id="docImageWidthLabel">80%</span><button type="button" data-action="imageLeft">Left</button><button type="button" data-action="imageCenter">Center</button><button type="button" data-action="imageRight">Right</button><button type="button" data-action="imageFloatLeft">Wrap text right</button><button type="button" data-action="imageFloatRight">Wrap text left</button><button type="button" data-action="imageBlock">Above / below text</button><button type="button" data-action="imageRemove">Remove image</button></div><div class="doc-canvas-wrap"><div id="richDoc" class="doc-paper ${d.layout==='magazine'?'magazine-page':''}" contenteditable="true" role="textbox" aria-label="Research paper content" aria-multiline="true" data-placeholder="Begin your research here. Add a heading, describe your question, include your findings, insert images and cite your sources…">${sanitizeRich(d.body)}</div></div><input type="hidden" name="layout" id="docLayout" value="${esc(d.layout||'research')}"><input type="hidden" name="body" id="richDocValue"><label class="label">Google Docs link (optional)</label><input class="field" name="doc_url" type="url" value="${esc(d.doc_url)}" placeholder="https://docs.google.com/document/..."><div class="row doc-actions"><button class="btn goldbtn" type="submit">Save document ↗</button><button class="btn linebtn" type="button" data-action="submitLocalDraft">Submit this draft to the Journal ↗</button><button class="btn linebtn" type="button" data-action="exportDraft">Download .html</button><button class="btn linebtn" type="button" data-action="exportText">Download .txt</button><span class="tiny" id="wordCount">0 words</span></div><p class="tiny">Save keeps this document on this browser and device. Download .html opens a formatted document in your browser; .txt is a plain-text backup without formatting. Browser-only drafts: not synced between devices. Inserted images count toward browser storage limits; export a copy. Never include patient records or sensitive personal data.</p></form></div>`);$('modal').classList.add('wide-modal');updateWordCount()}
function updateWordCount(){const e=$('richDoc');if(!e)return;const n=(e.innerText.trim().match(/\S+/g)||[]).length;$('wordCount').textContent=n+' words'}
function draftData(){const f=$('localDraftForm');if(!f)return null;const d=Object.fromEntries(new FormData(f));d.body=sanitizeRich($('richDoc')?.innerHTML||'');return d}
function downloadDraft(type){const d=draftData();if(!d)return;const filename=(d.title||'anatry-research').replace(/[^a-z0-9-_ ]/gi,'').slice(0,50);let content,mime,ext;if(type==='html'){content='<!doctype html><html><head><meta charset="utf-8"><title>'+esc(d.title)+'</title><style>body{font:17px/1.7 Georgia,serif;max-width:800px;margin:55px auto;padding:0 25px;color:#173328}img{max-width:100%;height:auto}h1,h2,h3{line-height:1.3}</style></head><body><h1>'+esc(d.title)+'</h1><p><b>'+esc(d.discipline)+'</b></p><h2>Abstract</h2><p>'+esc(d.abstract)+'</p><hr>'+d.body+'</body></html>';mime='text/html';ext='html'}else{content=[d.title,d.discipline,'ABSTRACT',d.abstract,'', $('richDoc')?.innerText||'',d.doc_url].join('\n');mime='text/plain';ext='txt'}const blob=new Blob([content],{type:mime+';charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename+'.'+ext;link.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function saveRichDraft(){const d=draftData();if(!d)return false;const all=getLocalDrafts();const idx=all.findIndex(x=>x.id===d.id);d.updated_at=new Date().toISOString();if(idx>=0)all[idx]=d;else all.unshift(d);const ok=storeLocalDrafts(all);if($('saveStatus'))$('saveStatus').textContent=ok?'Saved on this device':'Storage full — export a copy';return ok}
async function addRichImage(file){if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type))return toast('Choose a JPG, PNG or WebP photo.');if(file.size>12*1024*1024)return toast('Please choose an image under 12 MB.');try{const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1100/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.72);if(data.length>900000)return toast('Photo is too large for a browser draft. Try a smaller image.');$('richDoc').focus();document.execCommand('insertHTML',false,'<p><img src="'+data+'" alt="Research figure" style="max-width:100%;height:auto"></p><p><br></p>');updateWordCount();if($('saveStatus'))$('saveStatus').textContent='Unsaved changes'}catch(e){toast('Could not add this image. Try a different photo.')}}
const photoByField={Medicine:'https://images.unsplash.com/photo-1707944746508-f2dd7b88ac1b?w=900&q=78',Biology:'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=900&q=78',Chemistry:'https://images.unsplash.com/photo-1532634896-26909d0d4b8b?w=900&q=78',Physics:'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=900&q=78'};
