// Purpose-built vector science animations; no external photo dependency.
function scienceMotion(field,hero=false){
 const a='aria-hidden="true" focusable="false"';
 const base='class="science-motion science-'+field.toLowerCase()+(hero?' science-hero':'')+'" viewBox="0 0 420 220" preserveAspectRatio="xMidYMid meet" '+a;
 if(field==='Medicine')return `<svg ${base}><defs><linearGradient id="ecgInk" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#8dd9b5"/><stop offset="1" stop-color="#e6c889"/></linearGradient></defs><g class="motion-grid">${[50,90,130,170].map(y=>`<path d="M0 ${y}H420"/>`).join('')}${[60,120,180,240,300,360].map(x=>`<path d="M${x} 0V220"/>`).join('')}</g><path class="ecg-glow" d="M0 113H76l14-2 13-32 16 77 16-116 20 87 13-14h60l12-1 12-32 17 76 16-116 19 87 13-14H420"/><path class="ecg-line" d="M0 113H76l14-2 13-32 16 77 16-116 20 87 13-14h60l12-1 12-32 17 76 16-116 19 87 13-14H420"/><circle class="ecg-dot" cx="119" cy="156" r="4"/><text x="22" y="32" class="science-caption">CARDIAC RHYTHM / ECG</text><text x="370" y="197" class="science-caption">72 BPM</text></svg>`;
 if(field==='Biology'){let r='';for(let i=0;i<14;i++){let y=15+i*15,x1=210+Math.sin(i*.65)*79,x2=210-Math.sin(i*.65)*79;r+=`<line class="helix-rung" x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" style="animation-delay:${i*-.14}s"/><circle class="helix-a" cx="${x1}" cy="${y}" r="5"/><circle class="helix-b" cx="${x2}" cy="${y}" r="5"/>`;}return `<svg ${base}><g class="dna-drift">${r}</g><text x="24" y="30" class="science-caption">DNA / DOUBLE HELIX</text><text x="345" y="199" class="science-caption">A · T · G · C</text></svg>`}
 if(field==='Chemistry')return `<svg ${base}><g class="molecule-float"><g class="molecule-bonds"><path d="M125 115L185 70 252 96 298 146 239 179 167 165Z M185 70L202 127 167 165 M202 127L252 96 239 179 M125 115L202 127"/></g>${[[125,115,10],[185,70,12],[252,96,9],[298,146,13],[239,179,10],[167,165,11],[202,127,16]].map(([x,y,r],i)=>`<circle class="molecule-node n${i%3}" cx="${x}" cy="${y}" r="${r}"/>`).join('')}</g><text x="22" y="30" class="science-caption">MOLECULAR STRUCTURE</text><text x="321" y="200" class="science-caption">BONDS</text></svg>`;
 return `<svg ${base}><g class="orbit-system"><circle class="orbit-core" cx="210" cy="115" r="19"/><ellipse class="orbit-track" cx="210" cy="115" rx="128" ry="43" transform="rotate(-28 210 115)"/><ellipse class="orbit-track" cx="210" cy="115" rx="128" ry="43" transform="rotate(28 210 115)"/><ellipse class="orbit-track" cx="210" cy="115" rx="128" ry="43" transform="rotate(90 210 115)"/><g class="orbit-electron"><circle cx="338" cy="115" r="7"/></g><g class="orbit-electron orbit-two"><circle cx="338" cy="115" r="6"/></g></g><text x="22" y="30" class="science-caption">PHYSICS / MOTION</text><text x="332" y="200" class="science-caption">ENERGY</text></svg>`;
}
function scienceCardVisual(field){return `<div class="visual motion-visual ${field.toLowerCase()}">${scienceMotion(field)}<span class="motion-label">${field.toUpperCase()} <span class="motion-label-line"></span></span></div>`}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)}
function busyNotice(){return `<div class="notice">${configured?'Sign in to access this feature.':'Preview only. Connect Supabase in config.js and run sql/setup.sql to enable real accounts and shared data.'}</div>`}
function go(id){if(!names[id])id='home';view=id;location.hash=id;render();window.scrollTo({top:0,behavior:'smooth'})}
const disciplineThemes=['Medicine','Biology','Chemistry','Physics'];
function applyDisciplineTheme(){let choice='Medicine';try{choice=localStorage.getItem('anatry_discipline_theme')||profile?.discipline||'Medicine'}catch{}if(!disciplineThemes.includes(choice))choice='Medicine';document.documentElement.dataset.discipline=choice.toLowerCase();const picker=$('disciplineTheme');if(picker)picker.value=choice}
function changeDisciplineTheme(value){if(!disciplineThemes.includes(value))return;try{localStorage.setItem('anatry_discipline_theme',value)}catch{}applyDisciplineTheme()}
function renderNav(){const items=['home','discover','teams','studio','journal','mentors','faq','profile','safety',...(isAdmin?['admin']:[])];$('nav').innerHTML=items.map(id=>`<button class="navbtn ${view===id?'active':''}" data-go="${id}"><span>${icon[id]}</span>${names[id]}</button>`).join('');$('mobileNav').innerHTML=['home','teams','studio','journal','profile'].map(id=>`<button class="${view===id?'active':''}" data-go="${id}"><span>${icon[id]}</span>${names[id]}</button>`).join('');$('accountButton').textContent=session?'Account':'Sign in / Join';$('avatar').textContent=(profile?.display_name||'A')[0].toUpperCase();$('connectionBadge').textContent=configured?(session?'● Signed in':'● Live platform'):'Preview mode';if(!$('themeToggle')){const b=document.createElement('button');b.id='themeToggle';b.className='btn linebtn';b.type='button';b.setAttribute('aria-label','Switch light or dark mode');$('accountButton').before(b);b.onclick=toggleTheme} $('themeToggle').textContent=document.documentElement.dataset.theme==='light'?'☾ Dark':'☀ Light';if(!$('disciplineTheme')){const selector=document.createElement('select');selector.id='disciplineTheme';selector.className='theme-discipline-picker';selector.setAttribute('aria-label','Choose science discipline theme');selector.innerHTML=disciplineThemes.map(f=>`<option value="${f}">${f} theme</option>`).join('');$('themeToggle').before(selector);selector.onchange=e=>changeDisciplineTheme(e.target.value)}applyDisciplineTheme()}
const statFields=[['members','Members'],['publications','Publications'],['projects','Open projects'],['bahrain','In Bahrain'],['schools','Schools']];
function renderStats(){const value=k=>stats?Number(stats[k]||0).toLocaleString():'—';$('stats').innerHTML=statFields.map(([k,l])=>`<div class="stat"><span>${l}</span><strong>${value(k)}</strong></div>`).join('');return `<div class="counterstrip">${statFields.map(([k,l])=>`<div class="counterbox"><strong>${value(k)}</strong><span>${l}</span></div>`).join('')}</div>`}
function header(kicker,title,desc){return `<div class="reveal"><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><p class="lead">${desc}</p></div>`}
function home(){return `<section class="hero reveal"><div class="hero-science" aria-hidden="true">${scienceMotion('Medicine',true)}</div><span class="eyebrow">BORN IN BAHRAIN · OPEN TO THE WORLD</span><h1>Science is better <em>together.</em></h1><p>A new home for curious minds. Explore ideas, join mentor-led research teams, create something meaningful, and share your discoveries.</p><div class="hero-actions"><button class="btn goldbtn" data-go="teams">Find your research team ↗</button><button class="btn linebtn" data-go="journal">Read the Journal</button></div></section>${renderStats()}<div class="section-head"><div><span class="eyebrow">YOUR NEXT DISCOVERY</span><h2>Choose your curiosity.</h2></div><button class="textlink" data-go="discover">Explore all ↗</button></div><div class="cards">${demoTopics.map(t=>`<article class="card">${scienceCardVisual(t.field)}<p class="micro">${t.field.toUpperCase()}</p><h3>${t.title}</h3><p>${t.body}</p><button class="textlink" data-go="discover">Explore ${t.field} ↗</button></article>`).join('')}</div><div class="section-head"><div><span class="eyebrow">REAL RESEARCH, REAL CONNECTIONS</span><h2>Not just another science website.</h2></div></div><div class="cards"><article class="card"><span class="eyebrow">01 / CONNECT</span><h3>Meet your research team.</h3><p>Apply to join approved projects led by verified mentors. Learn how real collaborative research works.</p><button class="textlink" data-go="teams">Enter The Lab ↗</button></article><article class="card"><span class="eyebrow">02 / CREATE</span><h3>Write something worth reading.</h3><p>Draft your work, cite your sources, and submit for editorial review before publication.</p><button class="textlink" data-go="studio">Open the Studio ↗</button></article></div>`}
function discover(){return `${header('THE DISCOVERY FEED','Stay curious.','A beautifully simple starting point for your next science question.')}<div class="tabs">${['All',...fields].map(f=>`<button class="tab ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="cards">${demoTopics.filter(x=>filter==='All'||x.field===filter).map(t=>`<article class="card">${scienceCardVisual(t.field)}<span class="pill goldpill">${t.field}</span><h3>${t.title}</h3><p>${t.body}</p><button class="textlink" data-go="teams">Find related research ↗</button></article>`).join('')}</div>`}
function teams(){return `${header('THE LAB','Find your people.','Apply to join real mentor-led research projects. Every project and mentor is reviewed before appearing here.')}<div class="row" style="margin:23px 0"><button class="btn goldbtn" data-action="newProject">${mentorApproved||isAdmin?'Propose a project ↗':'How to lead a project ↗'}</button><button class="btn linebtn" data-go="mentors">Become a mentor</button></div>${!configured?busyNotice():''}<div class="section-head"><div><span class="eyebrow">OPEN OPPORTUNITIES</span><h2>Research teams</h2></div></div><div class="cards">${projects.filter(p=>p.status==='open').length?projects.filter(p=>p.status==='open').map(p=>`<article class="card"><span class="pill">${esc(p.discipline)}</span><span class="pill goldpill">Open applications</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="card-foot"><span class="small muted">Mentor-reviewed opportunity</span><button class="btn goldbtn" data-project="${p.id}">View & apply ↗</button></div></article>`).join(''):`<div class="panel" style="grid-column:1/-1"><span class="eyebrow">COMING TO LIFE</span><h3>Be part of the first research teams.</h3><p class="muted">No approved open projects yet. Verified mentors can propose a project, and the founder can approve it.</p></div>`}</div>${session?`<div class="section-head"><h2>Your team applications</h2></div><div class="panel">${myApplications.length?myApplications.map(a=>`<div class="list-item"><strong>${esc(projects.find(p=>p.id===a.project_id)?.title||'Project')}</strong> <span class="pill">${esc(a.status)}</span>${a.status==='approved'?`<button class="btn linebtn" data-room="${a.project_id}">Open team room</button>`:''}</div>`).join(''):'<p class="muted">You have not applied to a team yet.</p>'}</div>`:''}`}
const researchTemplates={
 research:`<h1>Research title</h1><p><em>Author · Institution · Date</em></p><h2>Abstract</h2><p>Summarize the question, approach, results and conclusion.</p><h2>Introduction</h2><p>Background, research question and hypothesis.</p><h2>Methods</h2><p>Study design, materials, procedures and ethical considerations.</p><h2>Results</h2><p>Present findings, tables and figures without interpretation.</p><h2>Discussion</h2><p>Interpret results, limitations and future work.</p><h2>Conclusion</h2><p>Summarize the key finding.</p><h2>References</h2><p>List all sources consistently.</p>`,
 magazine:`<p><em>ANATRY · SCIENCE FEATURE</em></p><h1>A question worth exploring</h1><h2>The discovery behind the story</h2><p><em>A short, compelling standfirst introducing the topic.</em></p><p>Start with a vivid, accurate explanation of the scientific question.</p><h2>Why it matters</h2><p>Explain the real-world importance in accessible language.</p><blockquote>Pull quote or a key finding to highlight.</blockquote><h2>What the research shows</h2><p>Describe evidence and include a labeled figure.</p><h2>What comes next?</h2><p>Open questions, limitations and future directions.</p><h2>Sources and further reading</h2><p>Add reliable citations and links.</p>`,
 medicine:`<h1>Medical research review</h1><p><em>Educational research only · No patient-identifying information</em></p><h2>Abstract</h2><h2>Clinical background</h2><h2>Research question</h2><h2>Evidence search and selection</h2><h2>Findings</h2><h2>Clinical significance</h2><h2>Limitations and ethics</h2><h2>Conclusion</h2><h2>References</h2>`,
 biology:`<h1>Biology laboratory report</h1><h2>Abstract</h2><h2>Biological background</h2><h2>Research question and hypothesis</h2><h2>Variables and controls</h2><h2>Materials and methods</h2><h2>Observations and results</h2><h2>Analysis and discussion</h2><h2>Limitations</h2><h2>Conclusion</h2><h2>References</h2>`,
 chemistry:`<h1>Chemistry investigation</h1><h2>Abstract</h2><h2>Research question</h2><h2>Chemical principles</h2><h2>Hypothesis and variables</h2><h2>Materials and safety considerations</h2><h2>Method</h2><h2>Results and calculations</h2><h2>Uncertainty and evaluation</h2><h2>Conclusion</h2><h2>References</h2>`,
 physics:`<h1>Physics investigation</h1><h2>Abstract</h2><h2>Research question</h2><h2>Theory and mathematical model</h2><h2>Hypothesis</h2><h2>Apparatus and procedure</h2><h2>Data and graphs</h2><h2>Calculations and uncertainty</h2><h2>Discussion</h2><h2>Conclusion</h2><h2>References</h2>`
};
let selectedDocImage=null,docAutosave=null;
function updateSelectedImage(img){selectedDocImage=img;const bar=$('docImageTools');if(!bar)return;bar.hidden=!img;if(img){const width=parseInt(img.style.width)||80;$('docImageWidth').value=width;$('docImageWidthLabel').textContent=width+'%'}}
function insertDocTemplate(name){const editor=$('richDoc');if(!editor||!researchTemplates[name])return;const hasText=editor.innerText.trim().length>15;if(hasText&&!confirm('Insert this template after your existing content?'))return;editor.insertAdjacentHTML('beforeend',researchTemplates[name]);if(name==='magazine'){$('docLayout').value='magazine';editor.classList.add('magazine-page')}editor.focus();updateWordCount();if($('saveStatus'))$('saveStatus').textContent='Unsaved changes'}
function studio(){const mine=publications.filter(p=>p.author_id===session?.user?.id);const local=getLocalDrafts();return `${header('RESEARCH STUDIO','Write what matters.','A real research-writing desk. Start a draft now, then connect your account when the secure backend is ready.')}<div class="studio-banner"><img src="assets/chemistry.svg" alt="Molecular science illustration"><div><span class="eyebrow">YOUR IDEAS DESERVE A WORKSPACE</span><h2>From your first question to your final paper.</h2><p>Write, edit, save and export your own drafts. No account needed to start.</p><button class="btn goldbtn" data-action="localDraft">+ Create a research draft</button></div></div><div class="section-head"><h2>My browser drafts</h2><span class="pill">${local.length} saved</span></div><div class="panel">${local.length?local.map(d=>`<div class="list-item"><span class="pill goldpill">${esc(d.discipline)}</span><h3>${esc(d.title||'Untitled research')}</h3><p>${esc(d.abstract||'Your research notes are ready.')}</p><div class="row"><button class="btn linebtn" data-localdraft="${esc(d.id)}">Continue writing ↗</button><button class="btn goldbtn" data-submitdraft="${esc(d.id)}">Submit to Journal ↗</button><button class="textlink" data-deletedraft="${esc(d.id)}">Delete</button></div></div>`).join(''):'<p class="muted">No drafts yet. Select “Create a research draft” above to start writing.</p>'}</div><div class="notice"><strong>One writing space:</strong> Write and save in the document editor above. When ready, select <strong>Submit to Journal</strong> on your saved draft. You will choose a subcategory, add references and confirm the originality declaration before editorial review. Drafts stay on this device until submitted.</div>${configured?`<div class="section-head"><h2>My Journal submissions</h2></div><div class="panel">${mine.length?mine.map(p=>`<div class="list-item"><span class="pill">${esc(p.status)}</span><h3>${esc(p.title)}</h3><button class="textlink" data-article="${p.id}">View submission ↗</button></div>`).join(''):'<p class="muted">No submitted papers yet. Your saved drafts are above.</p>'}</div>`:''}`}
function submitSavedDraft(id){
 const d=getLocalDrafts().find(x=>x.id===id);if(!d)return toast('Draft not found on this device.');
 if(!session)return authModal();
 const body=new DOMParser().parseFromString(d.body||'','text/html').body.textContent?.trim()||'';
 if((d.title||'').trim().length<5||!body||body.length<100)return toast('Add a title and at least 100 characters of research writing before submitting.');
 modal(`<h2 class="page-title">Submit your finished research</h2><p class="muted">Your saved document is ready. Add its publication details below; you do not need to rewrite your paper.</p><form id="articleForm"><input type="hidden" name="local_draft_id" value="${esc(d.id)}"><input type="hidden" name="title" value="${esc(d.title)}"><input type="hidden" name="discipline" value="${esc(d.discipline)}"><input type="hidden" name="abstract" value="${esc(d.abstract||body.slice(0,400))}"><textarea name="body" hidden>${esc(body)}</textarea><input type="hidden" name="doc_url" value="${esc(d.doc_url||'')}"><div class="submission-preview"><span class="eyebrow">${esc(d.discipline)}</span><h3>${esc(d.title)}</h3><p>${esc(d.abstract||body.slice(0,250))}</p><span class="tiny">${body.split(/\s+/).length} words</span></div><label class="label">Research subcategory *</label><select class="field" name="subcategory" required><option value="">Choose a subcategory…</option>${categoryOptions(d.discipline,'')}</select><label class="label">Sources and references *</label><textarea class="field" name="sources" rows="6" minlength="15" required placeholder="Author, title, year, publisher/journal, DOI or link. Include sources for figures and quotations."></textarea><label class="checkline"><input type="checkbox" name="originality_declaration" value="yes" required> I confirm this work is mine or properly attributed, any AI assistance is disclosed, and I have permission to use third-party materials.</label><div class="notice">Submissions are reviewed before public publication. Keep a copy of your browser draft until your article appears in the Journal.</div><button class="btn goldbtn" name="action" value="submitted" type="submit">Submit this draft for review ↗</button></form>${sourceGuide}`);
}
function journal(){const live=publications.filter(p=>p.status==='published');const authors=[...new Set(live.map(p=>p.author_name).filter(Boolean))].sort();const matches=live.filter(p=>(journalDiscipline==='All'||p.discipline===journalDiscipline)&&(journalSubcategory==='All'||p.subcategory===journalSubcategory)&&(journalAuthor==='All'||p.author_name===journalAuthor)&&[p.title,p.abstract,p.body,p.author_name,p.subcategory].join(' ').toLowerCase().includes(journalQuery.toLowerCase()));return `${header('THE ANATRY JOURNAL','Curiosity, published.','Discover student research by topic, specialty, or author. Every published article is reviewed by the editorial team.')}<section class="journal-cover"><div class="journal-cover-copy"><span class="eyebrow">ANATRY · THE RESEARCH EDITION</span><h2>Where questions become <em>discoveries.</em></h2><p>Explore science through evidence, clear writing, and original ideas.</p><button class="btn goldbtn" data-go="studio">Write for the Journal ↗</button></div></section>${categoryBrowser()}<div class="panel journal-search"><h2>Search research and people</h2><div class="journal-filter-grid"><label>Search papers or people<input class="field" id="journalSearch" value="${esc(journalQuery)}" placeholder="Heart, DNA, researcher name…"></label><label>Field<select class="field" id="journalField"><option>All</option>${fields.map(f=>`<option ${journalDiscipline===f?'selected':''}>${f}</option>`).join('')}</select></label><label>Subcategory<select class="field" id="journalSubcategory"><option>All</option>${(journalDiscipline==='All'?Object.values(journalCategories).flat():journalCategories[journalDiscipline]).map(c=>`<option ${journalSubcategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Author<select class="field" id="journalAuthor"><option>All</option>${authors.map(a=>`<option ${journalAuthor===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label></div><p class="tiny">Only authors with published articles appear in search. Private student profiles are not listed.</p></div>${researcherDirectory()}<div class="section-head"><h2>Published research</h2><span class="pill" id="journalCount">${matches.length} articles</span></div><div class="cards" id="journalResults">${journalCards(matches)}</div>${sourceGuide}<div class="section-head"><h2>FAQ & user guide</h2></div><div class="faq-grid"><div class="panel"><h3>How to use Anatry</h3><ol><li>Create an account and complete your profile.</li><li>Open Research Studio and start a draft or use a field template.</li><li>Use credible references and credit figures, images and quotations.</li><li>Choose your field and subcategory before submitting.</li><li>Wait for founder editorial review; only approved articles become public.</li></ol></div><div class="panel"><h3>Frequently asked questions</h3><details><summary>Can anyone publish instantly?</summary><p>No. Submissions are reviewed by a human editor before publication.</p></details><details><summary>Does Anatry guarantee a paper is AI-free or plagiarism-free?</summary><p>No. Automated checks are limited and can make mistakes. Authors must disclose AI assistance, provide sources, and undergo editorial review.</p></details><details><summary>Where are my drafts?</summary><p>Rich-text drafts are currently stored in the browser on this device. Export backups regularly.</p></details><details><summary>Can I submit a heart-related paper?</summary><p>Yes. Select Medicine, then Cardiology & the Heart.</p></details><details><summary>What if I use a copyrighted image or quote?</summary><p>Cite the creator and original source, and ensure you have permission or a valid license where required. A citation alone does not always grant permission.</p></details><details><summary>Can I change an article after submitting?</summary><p>Submitted articles are locked pending editorial review. Save a draft until you are ready.</p></details></div></div>`}
function faq(){return `${header('FAQ & USER GUIDE','Everything you need to begin.','A practical guide to researching, collaborating, and publishing responsibly on Anatry.')}<div class="faq-grid"><div class="panel"><h2>Start here</h2><ol><li>Create an account and choose your science discipline.</li><li>Write a draft in Research Studio. Try a research-paper or magazine template.</li><li>Use reliable sources and cite borrowed ideas, figures, and quotations.</li><li>Select the discipline and a specific subcategory.</li><li>Submit your article for editorial review; monitor its status in Research Studio.</li><li>Explore the Journal and search published authors and research topics.</li></ol></div><div class="panel"><h2>Frequently asked questions</h2><details><summary>Can I publish directly to the public Journal?</summary><p>No. Your article is submitted for editorial review. A beta label does not replace basic content and student-safety protections.</p></details><details><summary>How do I find people and their research?</summary><p>Use the Journal's researcher search or browse by field. Only names attached to public articles appear there; private accounts are not searchable.</p></details><details><summary>How can I work with mentors?</summary><p>Apply to join an approved research team through The Lab. Team notes are shared with approved members and moderators. Unrestricted private messaging is not enabled.</p></details><details><summary>What are the research subcategories?</summary><p>Each of the four fields has its own specialties. Pick one when you submit a paper so readers can find it.</p></details><details><summary>What about AI use, plagiarism, and copyright?</summary><p>Authors must cite sources, disclose relevant AI assistance, and obtain image permissions where needed. Anatry cannot guarantee automated detection; reports and editorial review are still necessary.</p></details><details><summary>Can I use photos in my drafts?</summary><p>Yes. Research Studio supports photos, resizing, and text wrapping. Use photos you own or are licensed to use and credit the creator.</p></details><details><summary>Where do my drafts go?</summary><p>The rich-text editor saves drafts on your current device. Export backups, especially before clearing browser data.</p></details><details><summary>What information should I avoid sharing?</summary><p>Do not post personal contact details, home addresses, school schedules, private grades, or medical information in public writing or team notes.</p></details></div></div>${sourceGuide}`}
function categoryBrowser(){return `<section class="panel journal-category-browser"><div class="section-head"><h2>Explore by specialty</h2><span class="tiny">Choose a discipline and research topic</span></div><div class="category-columns">${fields.map(f=>`<div class="category-column"><h3>${esc(f)}</h3>${journalCategories[f].map(c=>`<button type="button" class="category-chip ${journalDiscipline===f&&journalSubcategory===c?'selected':''}" data-category="${esc(f)}|${esc(c)}">${esc(c)}</button>`).join('')}</div>`).join('')}</div></section>`}
function researcherDirectory(){const grouped=new Map();for(const p of publications.filter(p=>p.status==='published'&&p.author_name)){const key=p.author_name.trim();if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(p)}const names=[...grouped.keys()].filter(n=>n.toLowerCase().includes(journalQuery.toLowerCase())||grouped.get(n).some(p=>[p.title,p.subcategory,p.discipline].join(' ').toLowerCase().includes(journalQuery.toLowerCase()))).sort();return `<section class="panel"><div class="section-head"><h2>Published researchers</h2><span class="pill">${names.length} researchers</span></div><p class="muted">Find contributors by name or subject and explore their published articles. Only public bylines are shown; private student profiles are not exposed.</p><div class="researcher-grid">${names.length?names.map(n=>`<div class="researcher-card"><div class="researcher-avatar">${esc(n[0].toUpperCase())}</div><div><strong>${esc(n)}</strong><p class="tiny">${grouped.get(n).length} published ${grouped.get(n).length===1?'article':'articles'}</p><button type="button" class="textlink" data-author="${esc(n)}">View publications ↗</button></div></div>`).join(''):'<p class="muted">No published researchers match yet.</p>'}</div></section>`}
function toggleTheme(){const theme=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('anatry_theme',theme)}catch{}renderNav()}
try{document.documentElement.dataset.theme=localStorage.getItem('anatry_theme')==='light'?'light':'dark'}catch{document.documentElement.dataset.theme='dark'}
function journalCards(list){return list.length?`<div class="research-feed">${list.map(p=>`<article class="feed-post"><div class="feed-byline"><div class="researcher-avatar">${esc((p.author_name||'A')[0].toUpperCase())}</div><div><strong>${esc(p.author_name||'Anatry contributor')}</strong><span>${esc(p.discipline)} · ${esc(p.subcategory||'Research')}</span></div><span class="pill goldpill">Published</span></div><div class="feed-visual"><img class="feed-photo" src="${photoByField[p.discipline]||photoByField.Medicine}" alt="${esc(p.discipline)} research photograph" loading="lazy"><div class="feed-motion-layer">${scienceMotion(p.discipline||'Medicine',false)}</div></div><div class="feed-copy"><h3>${esc(p.title)}</h3><p>${esc(p.abstract)}</p><div class="feed-actions"><button class="btn goldbtn" data-article="${p.id}">Read full paper ↗</button><button class="btn linebtn" data-author="${esc(p.author_name||'')}">More from author</button>${session&&p.author_id!==session.user.id?`<button class="btn linebtn" data-follow="${esc(p.author_id)}">${followedResearchers.has(p.author_id)?'Following ✓':'+ Follow researcher'}</button>`:''}</div></div></article>`).join('')}</div>`:'<div class="journal-empty"><div class="journal-empty-art">✦</div><div><h3>No published papers match yet.</h3><p>Try another topic or author. The first edition is growing.</p><button class="btn goldbtn" data-go="studio">Start a research draft ↗</button></div></div>'}

function mentors(){return `${header('MENTORSHIP','Help curiosity grow.','Medical students, science majors, graduate researchers and professors can apply to support the next generation.')}<div class="cards" style="margin-top:23px"><div class="card"><span class="eyebrow">MENTOR PATHWAY</span><h3>Guide a research team.</h3><p>Share your expertise, propose a project, review student work and help students develop research skills.</p><button class="btn goldbtn" data-action="mentorApply">${mentorApplication?'View my application':'Apply to mentor ↗'}</button></div><div class="card"><span class="eyebrow">SAFETY FIRST</span><h3>Verified, not anonymous.</h3><p>Applications are reviewed by Anatry before mentorship privileges are granted. Team discussions are visible to the project team and founder.</p><button class="textlink" data-go="safety">Read our safeguarding approach ↗</button></div></div>${mentorApplication?`<div class="notice success">Your mentor application status: <strong>${esc(mentorApplication.status)}</strong>.</div>`:''}`}
function profilePage(){if(!session)return `${header('YOUR SPACE','A profile built for discovery.','Sign in to view your projects, drafts and mentor applications.')}${busyNotice()}<button class="btn goldbtn" data-action="auth">Account information ↗</button>`;return `${header('MY ANATRY',esc(profile?.display_name||'Your profile'), 'Your private academic workspace and account settings.')}<div class="panel"><span class="pill">${esc(profile?.account_type||'student')}</span><span class="pill goldpill">${esc(profile?.discipline||'Biology')}</span><h3>Account information</h3><p class="muted">${esc(session.user.email)}</p><form id="profileForm"><label class="label">Display name</label><input class="field" name="display_name" required minlength="2" maxlength="70" value="${esc(profile?.display_name)}"><label class="label">Discipline</label><select class="field" name="discipline">${fields.map(f=>`<option ${profile?.discipline===f?'selected':''}>${f}</option>`).join('')}</select><label class="label">Location</label><select class="field" name="country"><option ${profile?.country==='Bahrain'?'selected':''}>Bahrain</option><option value="Other" ${profile?.country!=='Bahrain'?'selected':''}>Other</option></select><label class="label">School (optional; used only in aggregate counts)</label><input class="field" name="school" maxlength="100" value="${esc(profile?.school)}" placeholder="Leave blank if you prefer"><label class="label">Short bio</label><textarea class="field" name="bio" maxlength="350">${esc(profile?.bio)}</textarea><button class="btn goldbtn">Save profile</button></form><button class="btn linebtn" style="margin-top:16px" data-action="signout">Sign out</button></div>`}
function safety(){return `${header('PRIVACY & SAFETY','Science needs trust.','Our community is built to protect students and give researchers a respectful space to collaborate.')}<div class="cards" style="margin-top:24px"><div class="card"><span class="eyebrow">01 / PRIVATE BY DESIGN</span><h3>Private student information.</h3><p>Email addresses, school names and account details are not exposed in public listings. Public counters use aggregates only.</p></div><div class="card"><span class="eyebrow">02 / VERIFIED MENTORS</span><h3>Reviewed before access.</h3><p>Mentors apply first. The founder reviews credentials and approves mentor privileges before they can propose research projects.</p></div><div class="card"><span class="eyebrow">03 / TEAM COMMUNICATION</span><h3>No unmoderated private DMs.</h3><p>Project notes are visible to approved team members and founder moderators. Don't share addresses, phone numbers, or personal health details.</p></div><div class="card"><span class="eyebrow">04 / PUBLICATION REVIEW</span><h3>Editorial oversight.</h3><p>Research articles require review before becoming public. Report harassment, plagiarism, or unsafe conduct.</p></div></div><div class="panel"><h3>Report a concern</h3><p class="muted">Reports are only accessible to the person submitting them and authorized founder moderators.</p>${session?`<form id="reportForm"><label class="label">Type of concern</label><select class="field" name="category"><option value="harassment">Harassment</option><option value="privacy">Privacy</option><option value="misconduct">Research misconduct</option><option value="plagiarism">Plagiarism</option><option value="other">Other</option></select><label class="label">Details</label><textarea class="field" name="details" required minlength="10" maxlength="2000" placeholder="Describe the concern without sharing unnecessary personal information."></textarea><label class="label">Project or article reference (optional)</label><input class="field" name="reference" maxlength="300"><button class="btn goldbtn">Submit private report</button></form>`:busyNotice()}</div><p class="muted small">Important: Anatry's safeguarding policies, guardian consent where required, data retention and response procedures must be formally established before inviting minors to collaborate publicly.</p>`}
function admin(){if(!isAdmin)return header('RESTRICTED','Founder access only.','This area is available only to the founder account authorized in the database.');const renderItems=(arr,kind)=>arr?.length?arr.map(x=>`<div class="list-item"><span class="pill">${esc(x.status)}</span><h3>${esc(x.title||x.full_name||x.institution||x.category||'Application')}</h3><p>${esc(x.description||x.expertise||x.abstract||x.details||x.statement||'')}</p><span class="tiny">${esc(x.created_at?new Date(x.created_at).toLocaleDateString():'')}</span><div class="row" style="margin-top:10px">${kind==='mentors'?`<button class="btn linebtn" data-mentorview="${x.id}">View full application ↗</button>`:(kind==='projects'?['open','rejected','closed']:kind==='publications'?['published','rejected']:kind==='reports'?['reviewed','resolved']:[]).map(status=>`<button class="btn linebtn" data-review="${kind}|${x.id}|${status}">${status}</button>`).join('')}</div></div>`).join(''):'<p class="muted">Nothing waiting here.</p>';const pending=(adminData.mentors||[]).filter(x=>x.status==='pending');const reviewed=(adminData.mentors||[]).filter(x=>x.status!=='pending');return `${header('FOUNDER STUDIO','Review the community.','Open applications, examine supporting evidence, and record decisions.')}<div class="notice">Verify enrollment independently before approving mentors. Keep private documents confidential.</div><div class="panel"><div class="section-head"><h2>Mentor applications · Pending (${pending.length})</h2></div>${renderItems(pending,'mentors')}</div><details class="panel"><summary><strong>Reviewed mentor applications (${reviewed.length})</strong></summary>${renderItems(reviewed,'mentors')}</details>${[['projects','Project proposals'],['publications','Article submissions'],['reports','Safety reports']].map(([key,title])=>`<div class="panel"><div class="section-head"><h2>${title}</h2></div>${renderItems(adminData[key],key)}</div>`).join('')}`}
function mentorReviewModal(id){if(!isAdmin)return;const x=(adminData.mentors||[]).find(v=>v.id===id);if(!x)return;const line=(name,value)=>`<div class="review-field"><strong>${name}</strong><p>${esc(value||'Not provided')}</p></div>`;const docs=Array.isArray(x.documents)?x.documents:[];modal(`<h2 class="page-title">Mentor application</h2><span class="pill">${esc(x.status)}</span>${line('Full name',x.full_name)}${line('Institution',x.institution)}${line('University email',x.university_email)}${line('Degree / program',x.degree_program)}${line('Current year',x.study_year)}${line('Field of expertise',x.expertise)}${line('Experience',x.experience)}${line('Motivation',x.motivation)}<div class="review-field"><strong>Verification documents</strong>${docs.length?docs.map((d,i)=>`<p><button class="btn linebtn" data-mentordoc="${x.id}|${i}">View ${esc(d.type||'document')} · ${esc(d.name||'File')}</button></p>`).join(''):'<p>No documents attached.</p>'}</div>${x.status==='pending'?`<div class="row"><button class="btn goldbtn" data-review="mentors|${x.id}|approved">Approve mentor</button><button class="btn linebtn" data-review="mentors|${x.id}|rejected">Reject application</button></div>`:'<p class="muted">This application has already been reviewed.</p>'}`)}
async function openMentorDoc(id,index){const x=(adminData.mentors||[]).find(v=>v.id===id);const d=x?.documents?.[index];if(!d?.path)return;const {data,error}=await sb.storage.from('mentor-verification').createSignedUrl(d.path,90);if(error)return toast(error.message);window.open(data.signedUrl,'_blank','noopener,noreferrer')}

function render(){renderNav();$('content').innerHTML=({home,discover,teams,studio,journal,mentors,faq,profile:profilePage,safety,admin}[view]||home)();renderStats()}
function modal(html){$('modal').classList.remove('wide-modal');$('modal').innerHTML=`<div class="modalbox"><div class="modalhead"><span class="eyebrow">ANATRY</span><button class="close" data-action="close" aria-label="Close">×</button></div>${html}</div>`}
function close(){ $('modal').innerHTML=''; $('modal').classList.remove('wide-modal'); }
function authModal(){if(!configured){modal(`<h2 class="page-title">Accounts are not open yet.</h2><p class="muted">The account system needs a connected Supabase project, verified email sign-up and safeguarding checks before student registration can open.</p><p>Meanwhile, you can use the Research Studio to create and export drafts without signing up.</p><button class="btn goldbtn" data-go="studio">Open Research Studio ↗</button>`);return}if(session){go('profile');return}modal(`<h2 class="page-title">Welcome to Anatry.</h2><p class="muted">Secure sign-in, powered by Supabase. Choose an account type when registering.</p><div class="tabs"><button class="tab active" data-authmode="signin">Sign in</button><button class="tab" data-authmode="signup">Create account</button></div><form id="authForm"><div id="signupFields" style="display:none"><label class="label">Your display name</label><input class="field" name="display_name" maxlength="70"><label class="label">I'm joining as</label><select class="field" name="account_type"><option value="student">High school student</option><option value="mentor">University student / researcher / professor</option></select><label class="label">Discipline</label><select class="field" name="discipline">${fields.map(f=>`<option>${f}</option>`).join('')}</select><label class="label">Country</label><select class="field" name="country"><option>Bahrain</option><option>Other</option></select></div><label class="label">Email</label><input class="field" name="email" type="email" required autocomplete="email"><label class="label">Password</label><input class="field" name="password" type="password" required minlength="8" autocomplete="current-password"><button class="btn goldbtn" id="authSubmit" style="width:100%">Sign in securely ↗</button></form><p class="tiny">Use a unique password. Never include sensitive information in a public research article.</p>`)}
function projectModal(id){const p=projects.find(x=>x.id===id);if(!p)return;selectedProject=p;modal(`<span class="pill">${esc(p.discipline)}</span><h2 class="page-title">${esc(p.title)}</h2><p>${esc(p.description)}</p><div class="notice">Research collaboration is reviewed and team-based. No private one-to-one messaging.</div>${session?(p.owner_id===session.user.id?`<button class="btn goldbtn" data-room="${p.id}">Open your team room</button><div id="teamReview"></div>`:`<form id="teamApplyForm"><input type="hidden" name="project_id" value="${p.id}"><label class="label">Why would you like to join this research team?</label><textarea class="field" name="statement" required minlength="20" maxlength="1000"></textarea><button class="btn goldbtn">Apply to join ↗</button></form>`):`<p class="muted">Sign in to apply.</p><button class="btn goldbtn" data-action="auth">Sign in</button>`}`);if(session&&p.owner_id===session.user.id)loadTeamReview(p.id)}
function newProject(){if(!session)return authModal();if(!mentorApproved&&!isAdmin){toast('Only verified mentors can propose projects. Apply to mentor first.');go('mentors');return}modal(`<h2 class="page-title">Propose a research team.</h2><p class="muted">Projects become visible after founder review.</p><form id="projectForm"><label class="label">Project title</label><input class="field" name="title" minlength="5" maxlength="140" required><label class="label">Discipline</label><select class="field" name="discipline">${fields.map(f=>`<option>${f}</option>`).join('')}</select><label class="label">Research question and proposed activities</label><textarea class="field" name="description" minlength="30" maxlength="2500" required></textarea><button class="btn goldbtn">Submit for approval ↗</button></form>`)}
function mentorModal(){if(!session)return authModal();if(mentorApplication){modal(`<h2 class="page-title">Your mentor application</h2><p>Status: <strong>${esc(mentorApplication.status)}</strong></p><p class="muted">${esc(mentorApplication.status==='pending'?'Your application is awaiting review.':mentorApplication.status==='approved'?'You have been approved as a mentor.':'Your application was not approved.')}</p>`);return}modal(`<h2 class="page-title">Apply to become a mentor.</h2><p class="muted">Please complete the form and provide evidence of university enrollment. Only authorized reviewers can access your private supporting files.</p><form id="mentorForm"><label class="label">Full name</label><input class="field" name="full_name" required maxlength="120"><label class="label">University / institution</label><input class="field" name="institution" required minlength="2" maxlength="150"><label class="label">University email (optional)</label><input class="field" name="university_email" type="email" maxlength="160"><label class="label">Degree / program</label><input class="field" name="degree_program" required maxlength="150" placeholder="e.g. MBBS, BSc Chemistry"><label class="label">Current year of study</label><select class="field" name="study_year" required><option value="">Select year</option><option>Year 1</option><option>Year 2</option><option>Year 3</option><option>Year 4</option><option>Year 5+</option><option>Graduate / researcher</option><option>Faculty / professional</option></select><label class="label">Field of expertise</label><input class="field" name="expertise" required minlength="2" maxlength="120"><label class="label">Relevant research, teaching or mentoring experience</label><textarea class="field" name="experience" maxlength="2500"></textarea><label class="label">Why would you like to mentor?</label><textarea class="field" name="motivation" required minlength="20" maxlength="2000"></textarea><h3>Supporting documents</h3><p class="muted">Upload a CV and proof of current university enrollment (such as an enrollment certificate). Certificates or a transcript are optional. Please redact student ID numbers, home addresses, birth dates and grades that are not needed for verification.</p><label class="label">CV / résumé (PDF or image)</label><input class="field" type="file" name="cv_file" accept=".pdf,image/jpeg,image/png,image/webp" required><label class="label">Proof of enrollment (PDF or image)</label><input class="field" type="file" name="enrollment_file" accept=".pdf,image/jpeg,image/png,image/webp" required><label class="label">Certificates / transcript (optional)</label><input class="field" type="file" name="additional_file" accept=".pdf,image/jpeg,image/png,image/webp"><p class="tiny">Maximum 10 MB per document. Files are private and used only for mentor verification.</p><button class="btn goldbtn">Submit application ↗</button></form>`)}
async function uploadMentorFiles(form,uid){const docs=[];for(const [field,type] of [['cv_file','CV'],['enrollment_file','Enrollment proof'],['additional_file','Supporting document']]){const file=form.elements.namedItem(field)?.files?.[0];if(!file)continue;if(file.size>10*1024*1024)throw Error('Each document must be under 10 MB.');if(!['application/pdf','image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Only PDF, JPG, PNG and WebP files are accepted.');const extension=({ 'application/pdf':'pdf','image/jpeg':'jpg','image/png':'png','image/webp':'webp'})[file.type];const path=`${uid}/${crypto.randomUUID()}.${extension}`;const {error}=await sb.storage.from('mentor-verification').upload(path,file,{contentType:file.type,upsert:false});if(error)throw Error('Document upload failed: '+error.message);docs.push({type,name:file.name,path})}return docs}

function articleModal(id){const p=publications.find(x=>x.id===id);selectedArticle=p||null;if(!id){if(!session)return authModal();}if(p&&p.author_id!==session?.user.id&&p.status!=='published')return;const editable=!p||p.status==='draft';modal(`<h2 class="page-title">${editable?'Research Studio':'Publication'}</h2><p class="muted">${editable?'Write with care. Save drafts or submit for editorial review.':'Reviewed research writing.'}</p><form id="articleForm"><input type="hidden" name="id" value="${esc(p?.id||'')}"><label class="label">Title</label><input class="field" name="title" minlength="5" maxlength="160" required value="${esc(p?.title||'')}" ${editable?'':'readonly'}><label class="label">Discipline</label><select class="field" name="discipline" ${editable?'':'disabled'}>${fields.map(f=>`<option ${p?.discipline===f?'selected':''}>${f}</option>`).join('')}</select><label class="label">Research subcategory (required before submission)</label><select class="field" name="subcategory" id="articleSubcategory" ${editable?'':'disabled'}><option value="">Choose a subcategory…</option>${categoryOptions(p?.discipline||'Medicine',p?.subcategory)}</select><label class="label">Abstract</label><textarea class="field" name="abstract" minlength="30" maxlength="2000" required ${editable?'':'readonly'}>${esc(p?.abstract||'')}</textarea><label class="label">Full article / research writing</label><textarea class="field editor" name="body" minlength="100" maxlength="50000" required ${editable?'':'readonly'}>${esc(p?.body||'')}</textarea><label class="label">Sources and references (required before submission)</label><textarea class="field" name="sources" id="articleSources" rows="6" placeholder="List each source with author, title, year, journal or website, DOI/URL, and access date when appropriate" ${editable?'':'readonly'}>${esc(p?.sources||'')}</textarea><label class="checkline"><input type="checkbox" name="originality_declaration" value="yes" ${p?.originality_declaration?'checked':''} ${editable?'':'disabled'}> I wrote or appropriately credited this work, disclosed any AI assistance, and have permission to use third-party figures and images.</label><div class="notice">Pre-submission checks help flag missing citations and declarations. They cannot reliably determine AI authorship, plagiarism, or copyright ownership. Every paper still needs human editorial review.</div>${sourceGuide}<label class="label">Google Docs link (optional)</label><input class="field" name="doc_url" type="url" placeholder="https://docs.google.com/..." value="${esc(p?.doc_url||'')}" ${editable?'':'readonly'}>${p?.doc_url?`<a class="textlink" href="${esc(p.doc_url)}" target="_blank" rel="noopener noreferrer">Open linked Google Doc ↗</a>`:''}${editable?`<div class="row"><button class="btn linebtn" name="action" value="draft">Save draft</button><button class="btn goldbtn" name="action" value="submitted">Submit for review ↗</button></div>`:''}</form><p class="tiny">The editor stores plain text to prevent script injection. Google Docs remains an external link; it is not automatically synced.</p>`)}
function roomModal(id){if(!session)return authModal();selectedProject=projects.find(p=>p.id===id);modal(`<h2 class="page-title">Team room.</h2><p class="muted">Team notes are shared with approved members and founder moderators.</p><div id="roomNotes"><div class="skeleton"></div></div><form id="noteForm"><input type="hidden" name="project_id" value="${id}"><label class="label">Share a research update</label><textarea class="field" name="content" required maxlength="2000"></textarea><button class="btn goldbtn">Post to team ↗</button></form>`);loadRoom(id)}
async function loadRoom(id){const {data,error}=await sb.from('team_notes').select('*').eq('project_id',id).order('created_at',{ascending:false}).limit(60);if(!$('roomNotes'))return;$('roomNotes').innerHTML=error?`<div class="notice">${esc(error.message)}</div>`:data?.length?data.map(n=>`<div class="list-item"><span class="tiny">${new Date(n.created_at).toLocaleDateString()}</span><p>${esc(n.content)}</p></div>`).join(''):'<p class="muted">No team notes yet.</p>'}
async function loadTeamReview(id){const {data}=await sb.from('team_applications').select('*').eq('project_id',id);if(!$('teamReview'))return;$('teamReview').innerHTML=`<h3>Applications</h3>${data?.length?data.map(a=>`<div class="list-item"><span class="pill">${esc(a.status)}</span><p>${esc(a.statement)}</p>${a.status==='pending'?`<button class="btn linebtn" data-teamreview="${a.id}|approved">Approve</button> <button class="btn linebtn" data-teamreview="${a.id}|rejected">Decline</button>`:''}</div>`).join(''):'<p class="muted">No applications yet.</p>'}`}
async function fetchData(){if(!sb){stats=null;projects=[];publications=[];render();return}const [st,pr,pu]=await Promise.all([sb.rpc('community_stats'),sb.from('projects').select('*').order('created_at',{ascending:false}),sb.from('publications').select('*').order('published_at',{ascending:false,nullsFirst:false})]);stats=st.data||null;projects=pr.data||[];publications=pu.data||[];if(session){const uid=session.user.id;const [p,m,a,admin,following]=await Promise.all([sb.from('profiles').select('*').eq('id',uid).maybeSingle(),sb.from('mentor_applications').select('*').eq('user_id',uid).maybeSingle(),sb.from('team_applications').select('*').eq('user_id',uid),sb.rpc('is_admin'),sb.from('researcher_follows').select('followed_id').eq('follower_id',uid)]);followedResearchers=new Set((following.data||[]).map(x=>x.followed_id));profile=p.data;mentorApplication=m.data;myApplications=a.data||[];isAdmin=admin.data===true;mentorApproved=mentorApplication?.status==='approved';if(isAdmin)await loadAdmin()}else{profile=null;mentorApplication=null;myApplications=[];isAdmin=false;mentorApproved=false;followedResearchers=new Set()}render()}
async function loadAdmin(){const [m,p,a,r]=await Promise.all([sb.from('mentor_applications').select('*').order('created_at',{ascending:false}),sb.from('projects').select('*').order('created_at',{ascending:false}),sb.from('publications').select('*').order('created_at',{ascending:false}),sb.from('reports').select('*').order('created_at',{ascending:false})]);adminData={mentors:m.data||[],projects:p.data||[],publications:a.data||[],reports:r.data||[]}}
async function submitForm(form){if(!sb){toast('Connect Supabase to enable secure forms.');return}const data=Object.fromEntries(new FormData(form));const uid=session?.user?.id;const fail=e=>{toast(e.message||String(e));console.error(e)};try{if(form.id==='authForm'){const mode=form.dataset.mode||'signin';let result;if(mode==='signup'){result=await sb.auth.signUp({email:data.email,password:data.password,options:{data:{display_name:data.display_name,account_type:data.account_type,discipline:data.discipline,country:data.country}}})}else result=await sb.auth.signInWithPassword({email:data.email,password:data.password});if(result.error)throw result.error;close();toast(mode==='signup'&&!result.data.session?'Check your email to confirm your account.':'Welcome to Anatry.');await syncSession();return}if(!uid){authModal();return}let result;if(form.id==='mentorForm'){const documents=await uploadMentorFiles(form,uid);result=await sb.from('mentor_applications').insert({user_id:uid,full_name:data.full_name,institution:data.institution,university_email:data.university_email||null,degree_program:data.degree_program,study_year:data.study_year,experience:data.experience||null,expertise:data.expertise,motivation:data.motivation,documents})}else if(form.id==='projectForm'){result=await sb.from('projects').insert({owner_id:uid,title:data.title,discipline:data.discipline,description:data.description})}else if(form.id==='teamApplyForm'){result=await sb.from('team_applications').insert({user_id:uid,project_id:data.project_id,statement:data.statement})}else if(form.id==='noteForm'){result=await sb.from('team_notes').insert({project_id:data.project_id,author_id:uid,content:data.content})}else if(form.id==='articleForm'){if(data.action==='submitted'){const issues=reviewSubmission(data);if(issues.length){toast(issues[0]);return}}const row={title:data.title,discipline:data.discipline,subcategory:data.subcategory||null,sources:data.sources||'',originality_declaration:data.originality_declaration==='yes',author_name:profile?.display_name||'Anatry contributor',abstract:data.abstract,body:data.body,doc_url:data.doc_url||null,status:data.action==='submitted'?'submitted':'draft'};if(data.id){result=await sb.from('publications').update(row).eq('id',data.id)}else result=await sb.from('publications').insert({...row,author_id:uid})}else if(form.id==='profileForm'){result=await sb.from('profiles').update({display_name:data.display_name,discipline:data.discipline,country:data.country,school:data.school||null,bio:data.bio||''}).eq('id',uid)}else if(form.id==='reportForm'){result=await sb.from('reports').insert({reporter_id:uid,category:data.category,details:data.details,reference:data.reference||null})}if(result?.error)throw result.error;const isNote=form.id==='noteForm';const roomId=data.project_id;close();toast(form.id==='articleForm'&&data.action==='submitted'?'Submitted for editorial review. Your local draft remains saved.':'Saved successfully.');await fetchData();if(isNote)roomModal(roomId)}catch(e){fail(e)}}
async function syncSession(){if(!sb)return;const {data:{session:s}}=await sb.auth.getSession();session=s;await fetchData()}
async function handleReview(type,id,status){if(!isAdmin)return;const table={mentors:'mentor_applications',projects:'projects',publications:'publications',reports:'reports'}[type];if(!table)return;if(!confirm(`Confirm ${status} for this ${type} item?`))return;const update={status};if(type==='mentors')update.reviewed_at=new Date().toISOString();if(type==='publications'&&status==='published')update.published_at=new Date().toISOString();const {error}=await sb.from(table).update(update).eq('id',id);if(error)return toast(error.message);toast('Review saved');close();await fetchData()}
$('accountButton').onclick=()=>session?go('profile'):authModal();$('avatar').onclick=()=>go('profile');
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-go],[data-filter],[data-action],[data-project],[data-room],[data-article],[data-review],[data-teamreview],[data-authmode],[data-localdraft],[data-submitdraft],[data-deletedraft],[data-mentorview],[data-mentordoc],[data-category],[data-author],[data-follow]');if(!btn)return;if(btn.dataset.follow){if(!session)return authModal();const id=btn.dataset.follow;const following=followedResearchers.has(id);const result=following?await sb.from('researcher_follows').delete().eq('follower_id',session.user.id).eq('followed_id',id):await sb.from('researcher_follows').insert({follower_id:session.user.id,followed_id:id});if(result.error){toast(result.error.message);return}if(following)followedResearchers.delete(id);else followedResearchers.add(id);render();toast(following?'Unfollowed researcher':'Now following researcher');return}if(btn.dataset.category){const [f,c]=btn.dataset.category.split('|');journalDiscipline=f;journalSubcategory=c;journalAuthor='All';render();$('journalResults')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(btn.dataset.author){journalAuthor=btn.dataset.author;journalDiscipline='All';journalSubcategory='All';render();$('journalResults')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(btn.dataset.mentorview){mentorReviewModal(btn.dataset.mentorview);return}if(btn.dataset.mentordoc){const [id,i]=btn.dataset.mentordoc.split('|');await openMentorDoc(id,Number(i));return}if(btn.dataset.go){go(btn.dataset.go);return}if(btn.dataset.filter){filter=btn.dataset.filter;render();return}if(btn.dataset.localdraft){localDraftEditor(btn.dataset.localdraft);return}if(btn.dataset.submitdraft){submitSavedDraft(btn.dataset.submitdraft);return}if(btn.dataset.deletedraft){if(confirm('Delete this browser draft?')){storeLocalDrafts(getLocalDrafts().filter(x=>x.id!==btn.dataset.deletedraft));render();toast('Draft deleted.')}return}if(btn.dataset.project){projectModal(btn.dataset.project);return}if(btn.dataset.room){roomModal(btn.dataset.room);return}if(btn.dataset.article!==undefined){articleModal(btn.dataset.article);return}if(btn.dataset.review){const [type,id,status]=btn.dataset.review.split('|');await handleReview(type,id,status);return}if(btn.dataset.teamreview){const [id,status]=btn.dataset.teamreview.split('|');const {error}=await sb.from('team_applications').update({status}).eq('id',id);if(error)toast(error.message);else{toast('Application reviewed');loadTeamReview(selectedProject.id)}return}if(btn.dataset.authmode){$('authForm').dataset.mode=btn.dataset.authmode;$('signupFields').style.display=btn.dataset.authmode==='signup'?'block':'none';$('authSubmit').textContent=btn.dataset.authmode==='signup'?'Create account ↗':'Sign in securely ↗';document.querySelectorAll('[data-authmode]').forEach(b=>b.classList.toggle('active',b===btn));return}if(btn.dataset.action){switch(btn.dataset.action){case'auth':authModal();break;case'localDraft':localDraftEditor();break;case'submitLocalDraft':{const d=draftData();if(!d||!saveRichDraft()){toast('Could not save this draft. Please export a backup.');break}submitSavedDraft(d.id);break}case'exportDraft':downloadDraft('html');break;case'exportText':downloadDraft('txt');break;case'insertImage':$('docImageInput')?.click();break;case'insertRule':$('richDoc')?.focus();document.execCommand('insertHorizontalRule');break;case'insertQuote':$('richDoc')?.focus();document.execCommand('formatBlock',false,'blockquote');break;case'toggleMagazine':{const ed=$('richDoc');if(ed){const magazine=ed.classList.toggle('magazine-page');$('docLayout').value=magazine?'magazine':'research'}break}case'imageFloatLeft':case'imageFloatRight':case'imageBlock':if(selectedDocImage){selectedDocImage.style.float=btn.dataset.action==='imageBlock'?'none':btn.dataset.action==='imageFloatLeft'?'left':'right';selectedDocImage.style.margin=btn.dataset.action==='imageBlock'?'18px auto':btn.dataset.action==='imageFloatLeft'?'10px 22px 12px 0':'10px 0 12px 22px';}break;case'imageRemove':selectedDocImage?.remove();updateSelectedImage(null);updateWordCount();break;case'imageLeft':case'imageCenter':case'imageRight':if(selectedDocImage){selectedDocImage.style.marginLeft=btn.dataset.action==='imageLeft'?'0':'auto';selectedDocImage.style.marginRight=btn.dataset.action==='imageRight'?'0':'auto'}break;case'close':close();break;case'newProject':newProject();break;case'mentorApply':mentorModal();break;case'newArticle':articleModal();break;case'signout':await sb.auth.signOut();await syncSession();go('home');toast('Signed out');break}}});
document.addEventListener('submit',async e=>{if(e.target.id==='localDraftForm'){e.preventDefault();if(saveRichDraft()){close();render();toast('Document saved on this device.')}else toast('Browser storage is full. Download an HTML backup.');return}if(['authForm','mentorForm','projectForm','teamApplyForm','noteForm','articleForm','profileForm','reportForm'].includes(e.target.id)){e.preventDefault();const button=e.submitter;if(e.target.id==='articleForm'){e.target.querySelectorAll('input[name=action]').forEach(x=>x.remove());const hidden=document.createElement('input');hidden.type='hidden';hidden.name='action';hidden.value=button?.value||'draft';e.target.appendChild(hidden)}if(button)button.disabled=true;await submitForm(e.target);if(button?.isConnected)button.disabled=false}});
document.addEventListener('click',e=>{if(e.target.tagName==='IMG'&&e.target.closest('#richDoc')){e.preventDefault();updateSelectedImage(e.target)}else if(e.target.closest('#richDoc')&&!e.target.closest('img'))updateSelectedImage(null)});
let lastDocRange=null;document.addEventListener('selectionchange',()=>{const selection=window.getSelection();if(selection?.rangeCount&&$('richDoc')?.contains(selection.anchorNode))lastDocRange=selection.getRangeAt(0).cloneRange()});function restoreDocSelection(){if(!lastDocRange)return;const sel=window.getSelection();sel.removeAllRanges();sel.addRange(lastDocRange)}function colorUnderline(color){restoreDocSelection();const sel=window.getSelection();if(!sel||sel.isCollapsed)return;const range=sel.getRangeAt(0);const span=document.createElement('span');span.style.textDecoration='underline';span.style.textDecorationColor=color;span.style.textDecorationThickness='2px';try{range.surroundContents(span)}catch{document.execCommand('underline')}updateWordCount()}document.addEventListener('mousedown',e=>{if(e.target.closest('[data-format]'))e.preventDefault()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-format]');if(!b)return;e.preventDefault();$('richDoc')?.focus();document.execCommand(b.dataset.format,false,null);updateWordCount()});
document.addEventListener('change',e=>{if(e.target.id==='journalField'){journalDiscipline=e.target.value;journalSubcategory='All';render();return}if(e.target.id==='journalSubcategory'){journalSubcategory=e.target.value;render();return}if(e.target.id==='journalAuthor'){journalAuthor=e.target.value;render();return}if(e.target.closest('#articleForm')&&e.target.name==='discipline'){const c=$('articleSubcategory');if(c)c.innerHTML='<option value="">Choose a subcategory…</option>'+categoryOptions(e.target.value,'');return}if(e.target.id==='docTemplate'){insertDocTemplate(e.target.value);e.target.value=''}if(e.target.id==='docSize'){restoreDocSelection();document.execCommand('fontSize',false,e.target.value);$('richDoc')?.focus()}if(e.target.id==='docFont'){restoreDocSelection();document.execCommand('fontName',false,e.target.value);$('richDoc')?.focus()}if(e.target.id==='docHeading'){restoreDocSelection();document.execCommand('formatBlock',false,e.target.value);$('richDoc')?.focus()}if(e.target.id==='docColor'){restoreDocSelection();document.execCommand('foreColor',false,e.target.value);$('richDoc')?.focus()}if(e.target.id==='docHighlight'){restoreDocSelection();document.execCommand('hiliteColor',false,e.target.value);$('richDoc')?.focus()}if(e.target.id==='docUnderlineColor'){colorUnderline(e.target.value)}if(e.target.id==='docImageInput'){addRichImage(e.target.files?.[0]);e.target.value=''}});
document.addEventListener('input',e=>{if(e.target.id==='journalSearch'){journalQuery=e.target.value;const matching=publications.filter(p=>p.status==='published'&&(journalDiscipline==='All'||p.discipline===journalDiscipline)&&(journalSubcategory==='All'||p.subcategory===journalSubcategory)&&(journalAuthor==='All'||p.author_name===journalAuthor)&&[p.title,p.abstract,p.body,p.author_name,p.subcategory].join(' ').toLowerCase().includes(journalQuery.toLowerCase()));$('journalResults').innerHTML=journalCards(matching);$('journalCount').textContent=matching.length+' articles';return}if(e.target.id==='docImageWidth'&&selectedDocImage){selectedDocImage.style.width=e.target.value+'%';$('docImageWidthLabel').textContent=e.target.value+'%'}if(e.target.id==='richDoc'||e.target.id==='docImageWidth'||e.target.closest('#localDraftForm')&&['title','abstract','discipline','doc_url'].includes(e.target.name)){updateWordCount();if($('saveStatus'))$('saveStatus').textContent='Unsaved changes';clearTimeout(docAutosave);docAutosave=setTimeout(()=>{if($('localDraftForm'))saveRichDraft()},1800)}});
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(names[hash]&&view!==hash){view=hash;render()}});
view=names[location.hash.slice(1)]?location.hash.slice(1):'home';render();
if(configured){import('https://esm.sh/@supabase/supabase-js@2.49.10').then(({createClient})=>{sb=createClient(SUPABASE_URL,SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});sb.auth.onAuthStateChange((_event,newSession)=>{session=newSession;setTimeout(()=>fetchData(),0)});syncSession()}).catch(err=>{console.error(err);toast('Could not load the secure account service. Check your connection.');});}else{render();}

// Expand the research writing desk without changing or discarding the current draft.
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="docFullscreen"]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const root=$('modal');root.classList.toggle('editor-fullscreen');button.textContent=root.classList.contains('editor-fullscreen')?'⊟ Exit full screen':'⛶ Full screen';},{capture:true});
// Preserve a useful illustration when an external editorial photo is unavailable.
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||!img.matches('.feed-photo')||img.dataset.fallback)return;img.dataset.fallback='true';img.style.display='none';},{capture:true});